<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { fetchRemoteHosts, fetchRemotePerf, fetchRemoteProcesses, type RemoteHost, type RemotePoint, type RemoteProcessesResponse, type RemoteRange } from '@/api/remoteHosts'
import { freshnessText, offlineBannerText, fmtGb, fmtSize, fmtRss, fmtRate, runningFor, uptimeText, cacheText, sparkPath, sparkArea, mergePoints, memMix, niceMax, filterProcesses, sortProcesses } from '@/components/sched/remoteHostFormat'
import PerfChart from '@/components/sched/remote/PerfChart.vue'
import '@/components/sched/console.css'

const route = useRoute(), router = useRouter()
const name = computed(() => String(route.params.name))
const choice = <T extends string>(value: unknown, choices: readonly T[], fallback: T): T => choices.includes(value as T) ? value as T : fallback
const tab = computed(() => choice(route.query.tab, ['perf', 'tasks', 'procs'] as const, 'perf'))
const range = computed(() => choice(route.query.range, ['60s', '10m', '24h'] as const, '60s'))
const cpu = computed(() => choice(route.query.cpu, ['all', 'cores'] as const, 'all'))
const item = computed(() => choice(route.query.item, ['cpu', 'mem', 'disk', 'net'] as const, 'cpu'))
function select(key: string, value: string) { void router.replace({ query: { ...route.query, [key]: value } }) }
const host = ref<RemoteHost | null>(null), found = ref(false), points = ref<RemotePoint[]>([]), processes = ref<RemoteProcessesResponse | null>(null)
const failures = ref<Record<string, string>>({}), filter = ref(''), sortKey = ref<'name' | 'pid' | 'cpuPct' | 'rssMb'>('cpuPct'), sortDir = ref<'asc' | 'desc'>('desc')
const error = computed(() => Object.values(failures.value)[0] ?? '')
const latest = computed(() => host.value?.latest ?? null)
const rangeLabel = computed(() => ({ '60s': '60 秒', '10m': '10 分钟', '24h': '24 小时' })[range.value])
const tasks = computed(() => processes.value?.tasks ?? [])
const taskRows = computed(() => [...tasks.value.filter(t => t.kind !== 'system'), ...tasks.value.filter(t => t.kind === 'system')])
const rows = computed(() => sortProcesses(filterProcesses(processes.value?.processes ?? [], filter.value), sortKey.value, sortDir.value))
const mix = computed(() => latest.value?.mem?.usedMb != null && latest.value.mem.cachedMb != null && host.value?.host?.memTotalMb != null ? memMix(latest.value.mem, host.value.host.memTotalMb) : null)
const chartPoints = computed(() => points.value.filter(p => item.value === 'cpu' ? p.cpu != null : item.value === 'mem' ? p.mem?.usedMb != null : item.value === 'disk' ? p.disk?.busyPct != null : p.net?.rxBps != null && p.net?.txBps != null))
const values = computed(() => chartPoints.value.map(p => item.value === 'cpu' ? p.cpu : item.value === 'mem' ? p.mem.usedMb : item.value === 'disk' ? p.disk.busyPct : p.net.rxBps))
const color = computed<`--${string}`>(() => ({ cpu: '--chart-1', mem: '--chart-4', disk: '--chart-2', net: '--chart-3' })[item.value] as `--${string}`)
const max = computed(() => item.value === 'mem' ? host.value?.host?.memTotalMb ?? 0 : item.value === 'net' ? niceMax(points.value.flatMap(p => p.net ? [p.net.rxBps, p.net.txBps] : []), 1) : 100)
const diskPoints = computed(() => points.value.filter(p => p.disk?.readBps != null && p.disk?.writeBps != null))
const diskMax = computed(() => niceMax(diskPoints.value.flatMap(p => [p.disk.readBps, p.disk.writeBps]), 1))
let timers: number[] = [], controllers: Record<string, AbortController> = {}, active = false, generation = 0, primed = false
function stop() { generation++; timers.forEach(clearInterval); timers = []; Object.values(controllers).forEach(c => c.abort()); controllers = {} }
async function call(key: string, fn: (signal: AbortSignal) => Promise<void>) {
  if (controllers[key]) return
  const c = new AbortController(), current = generation; controllers[key] = c
  try { await fn(c.signal); if (active && current === generation && !c.signal.aborted) { const next = { ...failures.value }; delete next[key]; failures.value = next } }
  catch (e) { if (active && current === generation && !c.signal.aborted) failures.value = { ...failures.value, [key]: e instanceof Error ? e.message : String(e) } }
  finally { if (controllers[key] === c) delete controllers[key] }
}
function refreshHost() { void call('hosts', async signal => { const data = await fetchRemoteHosts(signal); if (!signal.aborted) { host.value = data.hosts.find(h => h.name === name.value) ?? null; found.value = true } }) }
function refreshPerf(initial = false) { void call('perf', async signal => { const selected = range.value, requestRange = selected === '10m' && !initial && primed ? '60s' : selected; const result = await fetchRemotePerf(name.value, requestRange, signal); if (!signal.aborted) { points.value = selected === '10m' && requestRange === '60s' ? mergePoints(points.value, result.points, 600) : result.points; primed = true } }) }
function refreshProcesses() { void call('processes', async signal => { const result = await fetchRemoteProcesses(name.value, signal); if (!signal.aborted) processes.value = result }) }
function start() {
  stop(); if (!active || document.visibilityState === 'hidden') return
  primed = false; refreshHost(); refreshPerf(true); refreshProcesses()
  timers.push(window.setInterval(refreshHost, 3000), window.setInterval(() => refreshPerf(), range.value === '24h' ? 30000 : 1000), window.setInterval(refreshProcesses, tab.value === 'perf' ? 30000 : 3000))
}
function visibility() { start() }
watch([range, tab, name], start)
onMounted(() => { active = true; document.addEventListener('visibilitychange', visibility); start() })
onUnmounted(() => { active = false; document.removeEventListener('visibilitychange', visibility); stop() })
function sort(key: typeof sortKey.value) { if (sortKey.value === key) sortDir.value = sortDir.value === 'asc' ? 'desc' : 'asc'; else { sortKey.value = key; sortDir.value = key === 'name' ? 'asc' : 'desc' } }
const sortAria = (key: typeof sortKey.value) => sortKey.value === key ? (sortDir.value === 'asc' ? 'ascending' : 'descending') : 'none'
const gbNumber = (n: number) => (n / 1024).toFixed(1)
</script>

<template>
  <main class="sched-page remote-page">
    <template v-if="found && !host"><div><button class="perf-back" @click="router.push('/sched')">返回调度台</button><p>没有这台远程机器</p></div></template>
    <div v-else-if="!host && error"><button class="perf-back" @click="router.push('/sched')">返回调度台</button><span class="bad">刷新失败:{{ error }}</span></div>
    <template v-else-if="host">
      <div class="perf-head"><button class="perf-back" @click="router.push('/sched')">返回调度台</button><h1>{{ host.label }}</h1><span class="freshness" :class="{ bad: host.stale }">{{ freshnessText(host.ageMs, host.stale) }}</span><span v-if="error" class="bad">刷新失败:{{ error }}</span><span class="seg tabs"><button v-for="t in (['perf','tasks','procs'] as const)" :key="t" :aria-pressed="tab === t" @click="select('tab', t)">{{ { perf:'性能', tasks:'任务', procs:'进程' }[t] }}</button></span></div>
      <div v-if="host.status === 'offline' || host.stale" class="offline-banner"><div><strong>连不上服务器</strong><br>{{ offlineBannerText(host.ageMs, host.error) }}</div></div>
      <div v-if="tab === 'perf'" class="perf-body">
        <nav class="perf-side" aria-label="性能项目"><button v-for="k in (['cpu','mem','disk','net'] as const)" :key="k" class="side-item" :aria-pressed="item === k" @click="select('item', k)"><svg v-if="!(k === 'mem' && (!host.host || host.host.memTotalMb == null))" viewBox="0 0 64 36" preserveAspectRatio="none"><path :d="sparkArea(points.map(p => k === 'cpu' ? p.cpu : k === 'mem' ? p.mem?.usedMb : k === 'disk' ? p.disk?.busyPct : p.net?.rxBps).filter((v): v is number => v != null), 64, 36, k === 'mem' ? host.host!.memTotalMb : k === 'net' ? niceMax(points.map(p => p.net?.rxBps).filter((v): v is number => v != null), 1) : 100)" :fill="`var(--chart-${{cpu:1,mem:4,disk:2,net:3}[k]})`" fill-opacity=".14"/><path :d="sparkPath(points.map(p => k === 'cpu' ? p.cpu : k === 'mem' ? p.mem?.usedMb : k === 'disk' ? p.disk?.busyPct : p.net?.rxBps).filter((v): v is number => v != null), 64, 36, k === 'mem' ? host.host!.memTotalMb : k === 'net' ? niceMax(points.map(p => p.net?.rxBps).filter((v): v is number => v != null), 1) : 100)" fill="none" :stroke="`var(--chart-${{cpu:1,mem:4,disk:2,net:3}[k]})`" vector-effect="non-scaling-stroke"/></svg><div v-else /><div><b>{{ k === 'cpu' ? 'CPU' : k === 'mem' ? '内存' : k === 'disk' ? `磁盘${latest?.disks?.length === 1 ? ' ' + latest.disks[0]?.name : ''}` : `网络${latest?.nets?.length === 1 ? ' ' + latest.nets[0]?.name : ''}` }}</b><span v-if="latest && (k === 'cpu' || (k === 'mem' && latest.mem) || (k === 'disk' && latest.disk) || (k === 'net' && latest.net))">{{ k === 'cpu' ? `${Math.round(latest.cpu)}%${latest.mhz == null ? '' : ` · ${(latest.mhz / 1000).toFixed(2)} GHz`}` : k === 'mem' ? (host.host?.memTotalMb != null ? `${gbNumber(latest.mem.usedMb)}/${gbNumber(host.host.memTotalMb)} GB(${Math.round(latest.mem.usedMb / host.host.memTotalMb * 100)}%)` : fmtGb(latest.mem.usedMb)) : k === 'disk' ? `${Math.round(latest.disk.busyPct)}%` : `收 ${fmtRate(latest.net.rxBps)} 发 ${fmtRate(latest.net.txBps)}` }}</span></div></button></nav>
        <section class="perf-main"><p v-if="!latest" class="sched-empty">还没收到数据</p><template v-else>
          <div class="perf-title"><h2>{{ { cpu:'CPU', mem:'内存', disk:'磁盘', net:'网络' }[item] }}</h2><span>{{ item === 'cpu' ? host.host?.cpuModel : item === 'mem' && host.host ? fmtGb(host.host.memTotalMb) : '' }}</span></div>
          <div class="perf-tools"><span class="seg"><button v-for="r in (['60s','10m','24h'] as const)" :key="r" :aria-pressed="range === r" @click="select('range', r)">{{ { '60s':'60 秒', '10m':'10 分钟', '24h':'24 小时' }[r] }}</button></span><div v-if="item === 'cpu'"><span class="seg"><button :aria-pressed="cpu === 'all' || range === '24h'" @click="select('cpu','all')">整体</button><button :aria-pressed="cpu === 'cores' && range !== '24h'" :disabled="range === '24h'" title="24 小时只有整体" @click="select('cpu','cores')">逻辑处理器</button></span><small v-if="range === '24h'">24 小时只有整体</small></div></div>
          <template v-if="item === 'cpu' && cpu === 'cores' && range !== '24h'"><div v-if="latest.cores" class="cores-grid"><div v-for="(_, i) in latest.cores" :key="i"><div class="core-cap"><span>{{ i }}</span><span>{{ latest.cores[i] }}%</span></div><svg viewBox="0 0 100 54" preserveAspectRatio="none"><path :d="sparkArea(points.flatMap(p => 'cores' in p && p.cores?.[i] != null ? [p.cores[i]!] : []),100,54,100)" fill="var(--chart-1)" fill-opacity=".14"/><path :d="sparkPath(points.flatMap(p => 'cores' in p && p.cores?.[i] != null ? [p.cores[i]!] : []),100,54,100)" fill="none" stroke="var(--chart-1)" vector-effect="non-scaling-stroke"/></svg></div></div></template>
          <template v-else-if="(item !== 'mem' || (host.host && host.host.memTotalMb != null)) && (item !== 'mem' || latest.mem) && (item !== 'disk' || latest.disk) && (item !== 'net' || latest.net)"><div class="chart-cap"><span>{{ item === 'cpu' ? `利用率 %${range === '24h' ? '(每分钟平均)' : ''}` : item === 'mem' ? '内存使用量' : item === 'disk' ? '活动时间 %' : '吞吐量' }}</span><span>{{ item === 'mem' && host.host ? fmtGb(host.host.memTotalMb) : item === 'net' ? fmtRate(max) : '100%' }}</span></div><PerfChart :points="chartPoints" :values="values" :second="item === 'net' ? chartPoints.map(p => p.net.txBps) : undefined" :max="max" :color="color" second-color="--chart-1" :range="range" :cpu="item === 'cpu'"/><div class="chart-cap"><span>{{ rangeLabel }}</span><span>0</span></div></template>
          <template v-if="item === 'disk' && diskPoints.length"><div class="chart-cap"><span>读写速度</span><span>{{ fmtRate(diskMax) }}</span></div><PerfChart :points="diskPoints" :values="diskPoints.map(p => p.disk.readBps)" :second="diskPoints.map(p => p.disk.writeBps)" :max="diskMax" color="--chart-2" second-color="--chart-1" :range="range" half/><div class="legend"><span><i class="legend-read"/>读取</span><span><i class="legend-write"/>写入</span></div></template>
          <template v-if="item === 'net' && latest.net"><div class="legend"><span><i class="legend-receive"/>接收</span><span><i class="legend-write"/>发送</span></div></template>
          <template v-if="item === 'mem' && mix && host.host"><div class="chart-cap">内存组合</div><div class="memmix"><i :style="{ width: `${mix.usedPct}%`, background:'var(--chart-4)' }"/><i :style="{ width: `${mix.cachePct}%`, background:'color-mix(in srgb, var(--chart-4) 35%, transparent)' }"/></div><div class="legend"><span><i class="legend-used"/>已用 {{ fmtGb(latest.mem.usedMb) }}</span><span><i class="legend-cache"/>缓存 {{ fmtGb(host.host.memTotalMb * mix.cachePct / 100) }}</span><span><i class="legend-free"/>空闲 {{ fmtGb(host.host.memTotalMb * mix.freePct / 100) }}</span></div></template>
          <div v-if="item === 'cpu'" class="perf-stats"><div v-if="latest.cpu != null"><small>利用率</small><b>{{ Math.round(latest.cpu) }}%</b></div><div v-if="latest.busyCores != null"><small>在用</small><b>{{ latest.busyCores }} 核</b></div><div v-if="latest.mhz != null"><small>速度</small><b>{{ (latest.mhz / 1000).toFixed(2) }} GHz</b></div><div v-if="latest.procs != null"><small>进程</small><b>{{ latest.procs }}</b></div><div v-if="latest.threads != null"><small>线程</small><b>{{ latest.threads }}</b></div><div v-if="latest.uptimeSec != null"><small>运行时间</small><b>{{ uptimeText(latest.uptimeSec) }}</b></div></div>
          <dl v-if="item === 'cpu' && host.host" class="perf-spec"><div v-if="host.host.sockets != null"><dt>插槽</dt><dd>{{ host.host.sockets }}</dd></div><div v-if="host.host.physicalCores != null"><dt>内核</dt><dd>{{ host.host.physicalCores }}</dd></div><div v-if="host.host.logicalCores != null"><dt>逻辑处理器</dt><dd>{{ host.host.logicalCores }}</dd></div><div v-if="host.host.virt !== undefined"><dt>虚拟机</dt><dd>{{ host.host.virt !== null ? '是' : '否' }}</dd></div><div v-if="host.host.cache?.l1d && host.host.cache?.l1i"><dt>L1 缓存(单核)</dt><dd>{{ cacheText(host.host.cache.l1d) }} + {{ cacheText(host.host.cache.l1i) }}</dd></div><div v-if="host.host.cache?.l2"><dt>L2 缓存(单核)</dt><dd>{{ cacheText(host.host.cache.l2) }}</dd></div><div v-if="host.host.cache?.l3"><dt>L3 缓存</dt><dd>{{ cacheText(host.host.cache.l3) }}</dd></div><div v-if="latest.load?.length === 3"><dt>负载</dt><dd>{{ latest.load.join(' / ') }}</dd></div><div v-if="latest.iowait != null"><dt>IO 等待</dt><dd>{{ latest.iowait }}%</dd></div><div v-if="latest.steal != null"><dt>宿主占用</dt><dd>{{ latest.steal }}%</dd></div></dl>
          <div v-if="item === 'mem' && latest.mem" class="perf-stats"><div v-if="latest.mem.usedMb != null"><small>使用中</small><b>{{ fmtGb(latest.mem.usedMb) }}</b></div><div v-if="latest.mem.availMb != null"><small>可用</small><b>{{ fmtGb(latest.mem.availMb) }}</b></div><div v-if="latest.mem.cachedMb != null"><small>已缓存</small><b>{{ fmtGb(latest.mem.cachedMb) }}</b></div><div v-if="latest.mem.commitMb != null && latest.mem.commitLimitMb != null"><small>已提交</small><b>{{ gbNumber(latest.mem.commitMb) }}/{{ fmtGb(latest.mem.commitLimitMb) }}</b></div><div v-if="latest.mem.swapUsedMb != null"><small>交换</small><b>{{ host.host?.swapTotalMb != null ? `${gbNumber(latest.mem.swapUsedMb)}/${fmtGb(host.host.swapTotalMb)}` : fmtGb(latest.mem.swapUsedMb) }}</b></div></div>
          <div v-if="item === 'disk' && latest.disk" class="perf-stats"><div v-if="latest.disk.busyPct != null"><small>活动时间</small><b>{{ Math.round(latest.disk.busyPct) }}%</b></div><div v-if="latest.disk.latencyMs != null"><small>平均响应</small><b>{{ latest.disk.latencyMs }} 毫秒</b></div><div v-if="latest.disk.readBps != null"><small>读取</small><b>{{ fmtRate(latest.disk.readBps) }}</b></div><div v-if="latest.disk.writeBps != null"><small>写入</small><b>{{ fmtRate(latest.disk.writeBps) }}</b></div></div><dl v-if="item === 'disk' && processes?.fs" class="perf-spec"><div v-for="fs in processes.fs" :key="fs.mount"><dt>{{ fs.mount }}</dt><dd>剩 {{ fmtSize(fs.availMb) }} / 共 {{ fmtSize(fs.totalMb) }}</dd></div></dl>
          <div v-if="item === 'net' && latest.net" class="perf-stats"><div v-if="latest.net.rxBps != null"><small>接收</small><b>{{ fmtRate(latest.net.rxBps) }}</b></div><div v-if="latest.net.txBps != null"><small>发送</small><b>{{ fmtRate(latest.net.txBps) }}</b></div></div>
        </template></section>
      </div>
      <section v-else-if="tab === 'tasks'" class="perf-main table-panel"><p v-if="!latest" class="sched-empty">还没收到数据</p><template v-else><div class="perf-title"><h2>任务</h2><span v-if="processes">{{ tasks.filter(t => t.kind !== 'system').length }} 个任务 · 合计 {{ tasks.filter(t => t.kind !== 'system').reduce((s,t) => s + t.cores,0).toFixed(1) }} 核</span></div><div v-if="processes" class="tbl-wrap"><table><thead><tr><th>任务</th><th>工作目录</th><th>CPU(核)</th><th>内存</th><th>进程</th><th>已运行</th></tr></thead><tbody><template v-for="task in taskRows" :key="task.id"><tr :class="task.kind === 'system' ? 'sched-muted' : task.cores >= (host.host?.logicalCores ?? Infinity) * .5 ? 'heat-2' : task.cores >= 1 ? 'heat-1' : ''"><td>{{ task.kind === 'system' ? '系统与后台' : task.label }}</td><td class="cmd">{{ task.cwd }}</td><td>{{ task.cores.toFixed(1) }}</td><td>{{ fmtRss(task.rssMb) }}</td><td>{{ task.pids }}</td><td>{{ runningFor(task.startedAt, Date.now()) }}</td></tr><tr v-for="p in task.kind === 'system' ? [] : task.top" :key="p.pid" class="sub"><td class="indent">{{ p.name }} · PID {{ p.pid }}</td><td/><td>{{ (p.cpuPct / 100).toFixed(2) }}</td><td>{{ fmtRss(p.rssMb) }}</td><td/><td/></tr></template></tbody></table></div></template></section>
      <section v-else class="perf-main table-panel"><p v-if="!latest" class="sched-empty">还没收到数据</p><template v-else><div class="perf-title"><h2>进程</h2><span v-if="processes">{{ processes.totals.processes }} 个进程 · {{ processes.totals.threads }} 个线程</span></div><input v-model="filter" class="field" placeholder="按名称、命令行或 PID 筛选" aria-label="筛选进程"><div class="tbl-wrap"><table><thead><tr><th v-for="col in (['name','pid','user','cpuPct','rssMb','threads','startedAt','command'] as const)" :key="col" :class="{ sorted: sortKey === col }" :aria-sort="['name','pid','cpuPct','rssMb'].includes(col) ? sortAria(col as typeof sortKey) : undefined"><button v-if="['name','pid','cpuPct','rssMb'].includes(col)" @click="sort(col as typeof sortKey)">{{ {name:'名称',pid:'PID',user:'用户',cpuPct:'CPU',rssMb:'内存',threads:'线程',startedAt:'已运行',command:'命令行'}[col] }}</button><template v-else>{{ {name:'名称',pid:'PID',user:'用户',cpuPct:'CPU',rssMb:'内存',threads:'线程',startedAt:'已运行',command:'命令行'}[col] }}</template></th></tr></thead><tbody><tr v-for="p in rows" :key="p.pid"><td>{{ p.name }}</td><td>{{ p.pid }}</td><td>{{ p.user }}</td><td>{{ p.cpuPct.toFixed(1) }}%</td><td>{{ fmtRss(p.rssMb) }}</td><td>{{ p.threads }}</td><td>{{ runningFor(p.startedAt, Date.now()) }}</td><td class="cmd">{{ p.command }}</td></tr><tr v-if="processes && !rows.length"><td colspan="8">没有匹配的进程</td></tr></tbody></table></div><p v-if="processes && processes.omitted > 0" class="sched-note">另有 {{ processes.omitted }} 个进程几乎不占 CPU 和内存,没列出</p></template></section>
    </template>
  </main>
</template>
<style scoped>
.remote-page { min-width:0; width:100%; }.perf-head { display:flex; flex-wrap:wrap; align-items:center; gap:var(--s2) var(--s4); }.perf-head h1 { margin:0; font-size:var(--fs-xl); }.freshness { font-size:var(--fs-xs); color:var(--text-3); }.freshness.bad { color:var(--bad); }.perf-back { border:0; background:none; padding:0; color:var(--text-2); cursor:pointer; font-size:var(--fs-sm); }.perf-back:hover { color:var(--info); text-decoration:underline; }.tabs { margin-left:auto; }
.seg { display:inline-flex; border:1px solid var(--line-strong); border-radius:var(--r); overflow:hidden; background:var(--surface); }.seg button { border:0; background:transparent; padding:4px 14px; cursor:pointer; color:var(--text-2); font-size:var(--fs-sm); min-height:32px; }.seg button + button { border-left:1px solid var(--line-strong); }.seg button[aria-pressed="true"] { background:var(--info-bg); color:var(--info); }.seg button:disabled { opacity:.5; cursor:default; }
.perf-body { display:grid; grid-template-columns:240px minmax(0,1fr); gap:var(--s4); margin-top:var(--s4); }.perf-side { display:flex; flex-direction:column; gap:var(--s1); }.side-item { display:grid; grid-template-columns:64px 1fr; gap:var(--s2); align-items:center; padding:var(--s2); border:1px solid transparent; border-radius:var(--r); background:transparent; cursor:pointer; text-align:left; }.side-item:hover { background:var(--surface-2); }.side-item[aria-pressed="true"] { background:var(--info-bg); border-color:var(--info); }.side-item svg { width:64px; height:36px; display:block; border:1px solid var(--line); background:var(--surface); }.side-item b { display:block; font-size:var(--fs-base); font-weight:600; }.side-item span { display:block; font-size:var(--fs-xs); color:var(--text-2); font-family:var(--mono); }
.perf-main { min-width:0; background:var(--surface); border:1px solid var(--line); border-radius:var(--r-lg); padding:var(--s4); }.table-panel { margin-top:var(--s4); }.perf-title { display:flex; flex-wrap:wrap; align-items:baseline; justify-content:space-between; gap:var(--s2); }.perf-title h2 { margin:0; font-size:var(--fs-2xl); font-weight:500; letter-spacing:-.01em; }.perf-title span { color:var(--text-2); font-size:var(--fs-sm); }.perf-tools { display:flex; flex-wrap:wrap; gap:var(--s2); justify-content:space-between; margin-top:var(--s3); }.perf-tools small { color:var(--text-3); font-size:var(--fs-xs); margin-left:var(--s2); }.chart-cap { display:flex; justify-content:space-between; color:var(--text-3); font-size:var(--fs-xs); margin-top:var(--s3); }
